function readable(m){const r=profile.role;if(r==='custom_admin')return modulePermissions.some(p=>p.module_key===m.key&&p.can_view);if(m.g===4)return false;if(m.n===61)return ['super_admin','admin','mosque_admin','manager'].includes(r)&&profile.institution!=='foundation';if(['super_admin','admin'].includes(r))return true;if(r==='auditor')return m.n===3||m.g===1||((m.g===2||m.g===4)&&profile.institution==='mosque')||((m.g===3||m.g===4)&&profile.institution==='foundation')||(profile.institution==='both'&&m.g>=2&&m.g<=4);if(r==='viewer')return m.g===1||((m.g===2||m.g===4)&&profile.institution==='mosque')||((m.g===3||m.g===4)&&profile.institution==='foundation')||(profile.institution==='both'&&m.g>=2&&m.g<=4);return m.n===1||m.g===1&&['website_admin','editor'].includes(r)||[15,16].includes(m.n)&&['website_admin','editor'].includes(r)||m.g===2&&['mosque_admin','manager'].includes(r)&&profile.institution!=='foundation'||m.g===3&&['foundation_admin','manager'].includes(r)&&profile.institution!=='mosque'||m.g===4&&['accountant','accounts_manager'].includes(r)}
