async function showModule(m,version=renderVersion){if(version!==renderVersion)return;active=m;Object.values(legacyPanels).forEach(p=>p?.remove());const w=$('adminWorkspace');if(!w)return;w.innerHTML='<h2>'+escapeHtml(m.name)+'</h2><p>'+escapeHtml(m.desc)+'</p><div class="actions"><button id="refreshModule">রিফ্রেশ</button><button id="exportModule">CSV ডাউনলোড</button></div><p id="moduleError" class="error" hidden></p><div id="moduleFormWrap"></div><h3>সংরক্ষিত তথ্য</h3><div id="legacyModulePanel"></div><div class="tablewrap"><table><thead><tr><th>শিরোনাম</th><th>প্রতিষ্ঠান</th><th>অবস্থা</th><th>হালনাগাদ</th><th>কাজ</th></tr></thead><tbody id="moduleRows"></tbody></table></div>';const contentModule=[13,15,16].includes(m.n)&&profile.role!=='custom_admin';const legacy=profile.role==='custom_admin'?null:contentModule?legacyPanels.content:m.n===14?legacyPanels.notices:m.n===3?legacyPanels.audit:m.n===55?legacyPanels.users:null;if(legacy){$('legacyModulePanel').append(legacy);legacy.hidden=false}if(contentModule){const category=m.n===13?'article':m.n===15?'gallery':m.n===16?'video':null;window.adminSetContentCategory?.(category);$('moduleFormWrap').innerHTML='';$('moduleRows').closest('.tablewrap').hidden=true;$('refreshModule').onclick=()=>window.adminContentRefresh?.();$('exportModule').onclick=()=>{const table=document.getElementById('siteContentRows');const lines=[['বিভাগ','স্লট','শিরোনাম','অবস্থা'],...[...(table?.rows||[])].map(r=>[...r.cells].slice(0,4).map(c=>c.innerText))];const csv='\\uFEFF'+lines.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='site-content.csv';a.click();URL.revokeObjectURL(url)};return}if(m.n===14&&profile.role!=='custom_admin'&&legacyPanels.notices){$('moduleFormWrap').innerHTML='';$('moduleRows').closest('.tablewrap').hidden=true;$('refreshModule').onclick=()=>location.reload();$('exportModule').onclick=()=>{const table=legacyPanels.notices.querySelector('table');if(!table)return;const csv='\\uFEFF'+[...table.rows].map(r=>[...r.cells].map(c=>'"'+c.innerText.replace(/"/g,'""')+'"').join(',')).join('\\r\\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='announcements.csv';a.click();URL.revokeObjectURL(u)};return}if(writable(m))form(m);else $('moduleFormWrap').innerHTML='<p class="notice">এই মডিউলটি শুধু দেখার অনুমতিতে রয়েছে।</p>';$('refreshModule').onclick=()=>load(m);$('exportModule').onclick=exportCsv;await load(m)}
