function fieldInput(field,value='',old={}){const [key,label,type='text',opts='']=field;const id='recordField_'+key;const safe=escapeHtml(value??'');if(type==='textarea')return '<div><label for="'+id+'">'+label+'</label><textarea id="'+id+'" rows="3" maxlength="12000">'+safe+'</textarea></div>';if(type==='select'){const other=opts.split('|').includes('অন্যান্য');return '<div><label for="'+id+'">'+label+'</label><select id="'+id+'"><option value="">নির্বাচন করুন</option>'+opts.split('|').map(v=>'<option value="'+escapeHtml(v)+'" '+(value===v?'selected':'')+'>'+escapeHtml(v)+'</option>').join('')+'</select>'+(other?'<div id="recordOtherWrap_'+key+'" '+(value==='অন্যান্য'?'':'hidden')+'><label for="recordField_'+key+'_other">অন্যান্য — বিস্তারিত লিখুন</label><textarea id="recordField_'+key+'_other" rows="2" maxlength="2000">'+escapeHtml(old[key+'_other']||'')+'</textarea></div>':'')+'</div>'}const imageField=type==='image'||(type==='url'&&(/(photo|image|poster|logo|cover|thumbnail|og_image)/i.test(key)||/(ছবি|ফটো|পোস্টার|লোগো|প্রচ্ছদ)/.test(label)));const uploadKind=type==='video'||key==='video_url'?'video':type==='file'||key==='document_url'?'file':imageField?'image':null;const inputType=['image','file','video'].includes(type)?'url':type;const accept=uploadKind==='video'?'video/mp4,video/webm,video/ogg':uploadKind==='file'?'.pdf,application/pdf,image/jpeg,image/png,image/webp':uploadKind==='image'?'image/jpeg,image/png,image/webp,image/gif':'';const upload=uploadKind?'<label for="recordUpload_'+key+'">সরাসরি '+(uploadKind==='video'?'ভিডিও':uploadKind==='file'?'ফাইল':'ছবি')+' আপলোড</label><input id="recordUpload_'+key+'" type="file" accept="'+accept+'"><small class="muted">আপলোড করলে URL স্বয়ংক্রিয়ভাবে বসবে।</small>':'';return '<div><label for="'+id+'">'+label+'</label><input id="'+id+'" type="'+inputType+'" value="'+safe+'" maxlength="2000" placeholder="https://...">'+upload+'</div>'}
function form(m,r=null){
 const wrap=$('moduleFormWrap');if(!wrap)return;const formVersion=renderVersion,schema=fieldSchemas[m.n]||[['description','বিস্তারিত বিবরণ','textarea'],['reference','তথ্যসূত্র/লিংক','url']];
 const publicId=privateOnlyModules.has(m.n)?null:(publicModuleMap[m.n]??null);
 const old=r?.data||{};
 wrap.innerHTML='<form id="moduleForm" class="panel"><h3>'+(r?'তথ্য সম্পাদনা':'নতুন তথ্য যোগ করুন')+'</h3><div class="formgrid"><div><label>শিরোনাম</label><input id="recordTitle" required maxlength="180"></div><div><label>প্রতিষ্ঠান</label><input value="'+(m.n===61||m.g===2?'মসজিদ':m.g===3?'ফাউন্ডেশন':institution(m)==='both'?'উভয় প্রতিষ্ঠান':institution(m)==='mosque'?'মসজিদ':'ফাউন্ডেশন')+'" disabled><input id="recordInstitution" type="hidden"></div><div><label>অবস্থা</label><select id="recordStatus"><option value="draft">খসড়া</option><option value="pending">অনুমোদনের অপেক্ষায়</option><option value="approved" '+(!canApprove(m)?'disabled':'')+'>অনুমোদিত</option><option value="published" '+(!canApprove(m)?'disabled':'')+'>প্রকাশিত</option></select></div></div><div class="formgrid">'+schema.map(f=>fieldInput(f,old[f[0]],old)).join('')+'</div><div class="actions"><button>সংরক্ষণ</button><button type="button" id="clearForm">নতুন এন্ট্রি</button></div></form>';
 $('recordTitle').value=r?.title||'';$('recordInstitution').value=institution(m);$('recordStatus').value=(r?.status==='published'&&!canApprove(m))?'pending':(r?.status||'draft');
 schema.filter(f=>f[2]==='select'&&f[3]?.split('|').includes('অন্যান্য')).forEach(([key])=>{const select=$('recordField_'+key),box=$('recordOtherWrap_'+key);select?.addEventListener('change',()=>{if(box)box.hidden=select.value!=='অন্যান্য'})});
 $('clearForm').onclick=()=>form(m);
 $('moduleForm').onsubmit=async e=>{e.preventDefault();const uploadedPaths=[];try{
  const requestedStatus=$('recordStatus').value,status=r?requestedStatus:(['approved','published'].includes(requestedStatus)?'pending':requestedStatus),data={...old,description:old.description||''};
  for(const [key,label,type,opts=''] of schema){const el=$('recordField_'+key);data[key]=el?.value?.trim?.()??'';if(type==='textarea'&&countWords500(data[key])>500)throw new Error(label+' সর্বোচ্চ ৫০০ শব্দের মধ্যে লিখুন।');if(type==='select'&&opts.split('|').includes('অন্যান্য')){const other=$('recordField_'+key+'_other')?.value?.trim()||'';if(data[key]==='অন্যান্য'&&!other)throw new Error('অন্যান্য নির্বাচন করলে বিস্তারিত লিখুন: '+label);data[key+'_other']=data[key]==='অন্যান্য'?other:'';}const imageField=type==='image'||(type==='url'&&(/(photo|image|poster|logo|cover|thumbnail|og_image)/i.test(key)||/(ছবি|ফটো|পোস্টার|লোগো|প্রচ্ছদ)/.test(label)));const kind=type==='video'||key==='video_url'?'video':type==='file'||key==='document_url'?'file':imageField?'image':null;const file=$('recordUpload_'+key)?.files?.[0];if(file&&kind){const rules=kind==='video'?{'video/mp4':'mp4','video/webm':'webm','video/ogg':'ogv'}:kind==='file'?{'application/pdf':'pdf','image/jpeg':'jpg','image/png':'png','image/webp':'webp'}:{'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'};if(!rules[file.type])throw new Error('এই ফাইলের ধরন সমর্থিত নয়: '+label);const max=kind==='video'?104857600:kind==='file'?26214400:10485760;if(file.size>max)throw new Error('ফাইলের আকার সীমা অতিক্রম করেছে: '+label);const path='modules/'+m.key+'/'+institution(m)+'/'+user.id+'/'+crypto.randomUUID()+'.'+rules[file.type];const{error:uploadError}=await supabase.storage.from('site-media').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(uploadError)throw uploadError;data[key]=supabase.storage.from('site-media').getPublicUrl(path).data.publicUrl;data[key+'_storage_path']=path;uploadedPaths.push(path);}}
  if(m.n===61&&data.consent!=='হ্যাঁ')throw new Error('মুসল্লীর তথ্য সংরক্ষণের আগে তাঁর সম্মতি আবশ্যক।');if(m.n===8&&!data.target_url)throw new Error('মেনু প্রকাশের জন্য পেজ URL বা লিংক দিন।');data.public_module=publicId;data.public_display=!privateOnlyModules.has(m.n);data.public_labels=Object.fromEntries(schema.flatMap(([key,label,type,opts=''])=>[[key,label],...(type==='select'&&opts.split('|').includes('অন্যান্য')?[[key+'_other',label+' — অন্যান্য']]:[])]));
  const p={module_key:m.key,institution:$('recordInstitution').value,title:$('recordTitle').value.trim(),data,status,approved_by:['approved','published'].includes(status)?user.id:(r?.approved_by||null),approved_at:['approved','published'].includes(status)?new Date().toISOString():(r?.approved_at||null),updated_at:new Date().toISOString()};
  let q;if(r){q=await supabase.from('module_records').update(p).eq('id',r.id)}else{q=await supabase.from('module_records').insert({...p,created_by:user.id}).select('id').single()}if(q.error)throw q.error;if(formVersion!==renderVersion)return;if(!r&&requestedStatus!==status){const approval=await supabase.from('module_records').update({status:requestedStatus,approved_by:user.id,approved_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',q.data.id);if(approval.error)throw approval.error}if(formVersion===renderVersion){form(m);await load(m,formVersion)}
 }catch(err){if(uploadedPaths.length)await supabase.storage.from('site-media').remove(uploadedPaths);const errorEl=$('moduleError');if(errorEl&&formVersion===renderVersion)showError(errorEl,err)}}
}
async function load(m,version=renderVersion){let data=[],offset=0;while(true){const{data:batch,error}=await supabase.from('module_records').select('id,module_key,institution,title,data,status,created_at,updated_at').eq('module_key',m.key).order('updated_at',{ascending:false}).range(offset,offset+299);if(version!==renderVersion)return;if(error){const errorEl=$('moduleError');if(errorEl)showError(errorEl,error);return}data=data.concat(batch||[]);if(!batch||batch.length<300)break;offset+=300}if(version!==renderVersion)return;rows=data;const body=$('moduleRows');if(!body)return;body.innerHTML=rows.map(r=>'<tr><td>'+escapeHtml(r.title)+'</td><td>'+escapeHtml(r.institution)+'</td><td>'+escapeHtml(({draft:'খসড়া',pending:'অপেক্ষমাণ',approved:'অনুমোদিত',published:'প্রকাশিত',archived:'আর্কাইভ',rejected:'বাতিল'})[r.status]||r.status)+'</td><td>'+escapeHtml(new Date(r.updated_at).toLocaleString('bn-BD'))+'</td><td><button data-edit="'+r.id+'" '+(!writable(m)?'disabled':'')+'>সম্পাদনা</button> <button data-approve="'+r.id+'" '+(!canApprove(m)||r.status!=='pending'?'disabled':'')+'>অনুমোদন</button> <button data-publish="'+r.id+'" '+(!canApprove(m)||r.status!=='approved'?'disabled':'')+'>প্রকাশ</button> <button data-delete="'+r.id+'" '+(profile.role!=='super_admin'?'disabled':'')+'>মুছুন</button></td></tr>').join('')||'<tr><td colspan="5">কোনো তথ্য পাওয়া যায়নি।</td></tr>';body.onclick=async e=>{const id=e.target.dataset.edit||e.target.dataset.approve||e.target.dataset.publish||e.target.dataset.delete;if(!id)return;const row=rows.find(x=>x.id===id);try{if(e.target.dataset.edit){form(m,row);return}if(e.target.dataset.approve||e.target.dataset.publish){const status=e.target.dataset.approve?'approved':'published';const{error}=await supabase.from('module_records').update({status,approved_by:user.id,approved_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',id);if(error)throw error}else if(e.target.dataset.delete){if(!confirm('এই রেকর্ড মুছবেন?'))return;const{error}=await supabase.from('module_records').delete().eq('id',id);if(error)throw error}await load(m,version)}catch(err){const errorEl=$('moduleError');if(errorEl&&version===renderVersion)showError(errorEl,err)}}}
function exportCsv(){const safe=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const csv='\uFEFF'+[['শিরোনাম','প্রতিষ্ঠান','অবস্থা','বিষয়ভিত্তিক তথ্য'],...rows.map(r=>[r.title,r.institution,r.status,Object.entries(r.data||{}).filter(([k,v])=>!['public_module','public_display','public_labels'].includes(k)&&v!==''&&v!==null&&v!==undefined).map(([k,v])=>(r.data?.public_labels?.[k]||k)+': '+v).join(' | ')])].map(x=>x.map(safe).join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=active.key+'-report.csv';a.click();URL.revokeObjectURL(u)}
async function boot(){try{if(!configured)return;const x=await currentProfile();user=x.user;profile=x.profile;if(!user||!profile)return;if(profile.role==='custom_admin'){const{data,error}=await supabase.from('admin_module_permissions').select('module_key,can_view,can_write,can_approve').eq('user_id',user.id);if(error)throw error;modulePermissions=data||[]}const app=$('app');if(app&&!app.hidden){shell();return}const ob=new MutationObserver(()=>{if(app&&!app.hidden){ob.disconnect();shell()}});if(app)ob.observe(app,{attributes:true,attributeFilter:['hidden']})}catch(e){console.error('Admin module initialization:',e)}}
boot();
